question:
Hàm sau kiểm tra điều gì, và chi phí của nó là bao nhiêu?
`function check(root) {
  const vals = [];
  function walk(node) {
    if (node === null) return;
    walk(node.left);
    vals.push(node.value);
    walk(node.right);
  }
  walk(root);
  return vals.every((v, i) => i === 0 || vals[i - 1] < v);
}`

