question:
Với cây có root 10, con trái 6 (các con 3 và 8) và con phải 15 (con phải 20), hàm sau trả về gì?
`function preOrder(root) {
  const stack = [root];
  const result = [];
  while (stack.length) {
    const node = stack.pop();
    result.push(node.value);
    if (node.left) stack.push(node.left);
    if (node.right) stack.push(node.right);
  }
  return result;
}`

